    M=np.maximum(M,M.T)
    for i in range(N):
        for j in (1,2):
            jj=(i+j)%N
            if rng.random()<0.1:
                nw=int(rng.integers(N))
                if nw!=i and M[i,nw]==0: M[i,jj]=0; M[jj,i]=0; M[i,nw]=1; M[nw,i]=1
